function validate([s, a, b, k]) {
  if (s.length < 1 || s.length > 500000) return 's has between 1 and 5 * 10^5 letters.';
  if (a.length < 1 || a.length > 500000 || b.length < 1 || b.length > 500000) return 'a and b each have between 1 and 5 * 10^5 letters.';
  if (!/^[a-z]+$/.test(s) || !/^[a-z]+$/.test(a) || !/^[a-z]+$/.test(b)) return 's, a and b use only lowercase English letters.';
  if (!Number.isInteger(k) || k < 1 || k > s.length) return 'k is an integer between 1 and s.length.';
  return null;
}

