function beautifulIndices(s, a, b, k) {
  const findStarts = (pattern) => {
    const text = pattern + '#' + s;
    const lps = new Array(text.length).fill(0);
    const starts = [];
    for (let i = 1; i < text.length; i++) {
      let length = lps[i - 1];
      while (length > 0 && text[i] !== text[length]) {
        length = lps[length - 1];
      }
      if (text[i] === text[length]) {
        length++;
      }
      lps[i] = length;
      if (length === pattern.length) {
        starts.push(i - 2 * pattern.length);
      }
    }
    return starts;
  };
  const startsA = findStarts(a);
  const startsB = findStarts(b);
  const result = [];
  let j = 0;
  for (const i of startsA) {
    while (j < startsB.length && startsB[j] < i - k) {
      j++;
    }
    if (j < startsB.length && startsB[j] <= i + k) {
      result.push(i);
    }
  }
  return result;
}

