function beautifulIndices(s, a, b, k) {
  const occurs = (pattern, at) => at + pattern.length <= s.length && s.slice(at, at + pattern.length) === pattern;
  const answer = [];
  for (let i = 0; i < s.length; i++) {
    if (!occurs(a, i)) continue;
    let found = false;
    for (let j = 0; j < s.length && !found; j++) {
      if (Math.abs(i - j) <= k && occurs(b, j)) found = true;
    }
    if (found) answer.push(i);
  }
  return answer;
}

