function generate(rand, size) {
  const large = size === 'large';
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const alphabet = [1, 2, 3, large ? 26 : 4][Math.floor(rand() * 4)];
  const n = large ? 10000 : 1 + Math.floor(rand() * 12);
  let s = '';
  for (let i = 0; i < n; i++) s += letters[Math.floor(rand() * alphabet)];
  const maxPattern = large ? 1 + Math.floor(rand() * 8) : 4;
  const pattern = () => {
    const length = 1 + Math.floor(rand() * maxPattern);
    if (rand() < 0.75 && length <= n) {
      const start = Math.floor(rand() * (n - length + 1));
      return s.slice(start, start + length);
    }
    let text = '';
    for (let i = 0; i < length; i++) text += letters[Math.floor(rand() * alphabet)];
    return text;
  };
  const a = pattern();
  const b = pattern();
  const k = large ? 1 + Math.floor(rand() * (rand() < 0.5 ? 50 : n)) : 1 + Math.floor(rand() * n);
  return [s, a, b, k];
}
